import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class FileHandlerFixed {
    public static void readUserFile(String filename) throws IOException {
        String filePath = "/var/www/data/" + filename;

        // Fix: Ensure the resolved path is within the allowed base directory
        Path basePath = Paths.get("/var/www/data").toAbsolutePath().normalize();
        Path userPath = Paths.get(filePath).toAbsolutePath().normalize();

        if (!userPath.startsWith(basePath)) {
            throw new SecurityException("Attempted access outside of allowed directory");
        }

        File file = userPath.toFile();
        if (file.exists() && file.isFile()) {
            byte[] fileContent = Files.readAllBytes(userPath);
            // ... process file content ...
        }
    }
}
